    }

    static WHISPER_TEXT text;
    text.m_bIsSelected = FALSE;
    wcsncpy(text.m_szID, pszID, MAX_USERNAME_SIZE + 1);
    //memcpy(text.m_szID, pszID, wcslen(pszID) + 1);
